//! The Node 22 name universe that the scanner's Node-parity rules check against. The data is generated by
//! `tools/scan-names/gen.js` (see the header of `data/node22_names.txt`); nothing here reads the host.
//! Lookups are by name only: `is_node_method_name` (any string key reachable on a Node builtin),
//! `is_node_global` (own key of `globalThis`), and `node_global_has` (own or inherited key of a
//! `process`, `Symbol`, `crypto`, `globalThis` or `navigator` member).

use std::collections::{HashMap, HashSet};
use std::sync::OnceLock;

const DATA: &str = include_str!("data/node22_names.txt");

struct Names {
    node_version: &'static str,
    methods: HashSet<&'static str>,
    globals: HashSet<&'static str>,
    members: HashMap<&'static str, HashSet<&'static str>>,
}

fn names() -> &'static Names {
    static NAMES: OnceLock<Names> = OnceLock::new();
    NAMES.get_or_init(|| parse(DATA))
}

fn parse(data: &'static str) -> Names {
    let mut out = Names {
        node_version: "",
        methods: HashSet::new(),
        globals: HashSet::new(),
        members: HashMap::new(),
    };
    let mut section = "";
    for line in data.lines() {
        if let Some(v) = line.strip_prefix("# node: ") {
            out.node_version = v;
        } else if let Some(s) = line.strip_prefix("#section ") {
            section = s;
        } else if line.starts_with('#') || line.is_empty() {
            continue;
        } else {
            match section {
                "methods" => {
                    out.methods.insert(line);
                }
                "globals" => {
                    out.globals.insert(line);
                }
                "members" => {
                    if let Some((root, key)) = line.split_once('.') {
                        out.members.entry(root).or_default().insert(key);
                    }
                }
                _ => {}
            }
        }
    }
    out
}

/// The Node version the data was generated with, e.g. `v22.23.1`.
pub fn node_version() -> &'static str {
    names().node_version
}

/// True if some Node 22 builtin (export, class, prototype, `globalThis`, diagnostics channel or child IPC
/// channel) has a string key `name`.
pub fn is_node_method_name(name: &str) -> bool {
    names().methods.contains(name)
}

/// True if `name` is an own property of Node 22's `globalThis`.
pub fn is_node_global(name: &str) -> bool {
    names().globals.contains(name)
}

/// True if Node 22 has `member` (own or inherited) on the global `global`, for the members the data covers
/// (`process`, `Symbol`, `crypto`, `globalThis`, `navigator`). Any other `global` gives false.
pub fn node_global_has(global: &str, member: &str) -> bool {
    names()
        .members
        .get(global)
        .is_some_and(|set| set.contains(member))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn header_records_node_version() {
        let first = DATA.lines().next().unwrap_or("");
        assert!(first.starts_with("# node: v22."), "header line: {first:?}");
        assert!(
            node_version().starts_with("v22."),
            "version: {:?}",
            node_version()
        );
    }

    #[test]
    fn well_known_node_names_are_present() {
        for name in [
            "readFileSync",
            "createServer",
            "nextTick",
            "randomBytes",
            "publish",
            "runStores",
        ] {
            assert!(is_node_method_name(name), "{name}");
        }
        assert!(node_global_has("Symbol", "asyncIterator"));
        assert!(node_global_has("process", "nextTick"));
        assert!(node_global_has("process", "dlopen"));
    }

    #[test]
    fn package_local_names_are_absent() {
        for name in [
            "customMerge",
            "allowRequest",
            "_once",
            "getTracer",
            "setStatus",
            "getColumnCasing",
        ] {
            assert!(!is_node_method_name(name), "{name}");
        }
        // Environment-variable names must never leak into the data (they depend on the generating machine).
        assert!(!is_node_method_name("HOME"));
    }

    #[test]
    fn node_names_that_collide_with_thaw_gaps_are_present() {
        // Real Node names (child_process IPC channel, pg/drizzle collisions): the data must not drop them.
        for name in ["refCounted", "unrefCounted", "execute", "isConnected"] {
            assert!(is_node_method_name(name), "{name}");
        }
    }

    #[test]
    fn globals_match_node_globalthis() {
        for name in ["fetch", "globalThis", "process", "navigator"] {
            assert!(is_node_global(name), "{name}");
        }
        for name in [
            "window",
            "document",
            "requestAnimationFrame",
            "cancelAnimationFrame",
            "WorkerGlobalScope",
        ] {
            assert!(!is_node_global(name), "{name}");
        }
    }

    #[test]
    fn members_absent_on_node_22_are_absent() {
        // The note's claims: each of these is undefined on Node 22 too.
        assert!(!node_global_has("process", "noDeprecation"));
        assert!(!node_global_has("process", "traceDeprecation"));
        assert!(!node_global_has("Symbol", "observable"));
        assert!(!node_global_has("crypto", "randomBytes"));
        assert!(!node_global_has("navigator", "product"));
        assert!(
            !node_global_has("Math", "random"),
            "roots outside the data give false"
        );
    }

    #[test]
    fn data_is_not_trivially_small() {
        assert!(
            names().methods.len() > 3000,
            "methods: {}",
            names().methods.len()
        );
        assert!(
            names().globals.len() > 100,
            "globals: {}",
            names().globals.len()
        );
    }
}
